



















































































































-- Normalize demo catalog ownership: each product belongs to a merchant and brand
-- that match its category, with leaf-level refinement for health & beauty.
-- 1) Reassign products to merchants whose business matches the product category root.
WITH mapping(merchant_name, root_name) AS (VALUES
  ('ActiveGlow Sports', 'Thể thao & Dã ngoại'),
  ('ActiveLine', 'Thời trang'),
  ('Aionn Tech Store', 'Điện tử'),
  ('Apex Smart Life', 'Nhà thông minh'),
  ('ApplianceHub', 'Nhà cửa & Bếp'),
  ('AudioWave Store', 'Điện tử'),
  ('Aura Closet', 'Thời trang'),
  ('AutoDrive', 'Ô tô & Xe máy'),
  ('BeautyBar', 'Sức khỏe & Làm đẹp'),
  ('BioVital Health', 'Sức khỏe & Làm đẹp'),
  ('CarryLux', 'Thời trang'),
  ('CasaNova', 'Nhà cửa & Bếp'),
  ('CozyHome', 'Nhà cửa & Bếp'),
  ('CyberTech Hub', 'Điện tử'),
  ('DailyGrocer', 'Nhà cửa & Bếp'),
  ('DigitalBay', 'Điện tử'),
  ('Eco Living Co', 'Nhà cửa & Bếp'),
  ('Elegance Fashion', 'Thời trang'),
  ('FitGear', 'Thể thao & Dã ngoại'),
  ('FitLife Athletics', 'Thể thao & Dã ngoại'),
  ('FreshSip', 'Nhà cửa & Bếp'),
  ('GemStory', 'Thời trang'),
  ('Glow Beauty', 'Sức khỏe & Làm đẹp'),
  ('HairCare Lab', 'Sức khỏe & Làm đẹp'),
  ('HomeAura', 'Nhà cửa & Bếp'),
  ('KitchenCraft', 'Nhà cửa & Bếp'),
  ('Kraft Furnishings', 'Nhà cửa & Bếp'),
  ('LuxTime Boutique', 'Thời trang'),
  ('MarketOne', 'Nhà cửa & Bếp'),
  ('MotoCity', 'Ô tô & Xe máy'),
  ('Nexus Electronics', 'Điện tử'),
  ('PixelMart', 'Điện tử'),
  ('PlaySport', 'Thể thao & Dã ngoại'),
  ('PureCare Cosmetics', 'Sức khỏe & Làm đẹp'),
  ('PureGlow Store', 'Sức khỏe & Làm đẹp'),
  ('ScentHouse', 'Sức khỏe & Làm đẹp'),
  ('ShadeVibe', 'Thời trang'),
  ('SmartNest', 'Nhà thông minh'),
  ('SportZone', 'Thể thao & Dã ngoại'),
  ('StyleNest', 'Thời trang'),
  ('TabWorld', 'Điện tử'),
  ('TechSphere', 'Điện tử'),
  ('TrailPro', 'Thể thao & Dã ngoại'),
  ('TrendHaus', 'Thời trang'),
  ('UrbanThread', 'Thời trang'),
  ('Vina Gadgets', 'Điện tử'),
  ('VitaPlus', 'Sức khỏe & Làm đẹp'),
  ('WearTech', 'Điện tử'),
  ('WheelWorks', 'Ô tô & Xe máy'),
  ('Zephyr Home Comfort', 'Nhà cửa & Bếp')
),
merchant_domain AS (
  SELECT m.merchant_id, mp.root_name
  FROM merchants m
  JOIN mapping mp ON mp.merchant_name = m.name
),
prod_root AS (
  SELECT p.product_id, p.merchant_id,
         (SELECT c.name
            FROM jsonb_array_elements_text(p.category_ids) AS cid
            JOIN categories c ON c.category_id = cid AND c.parent_id IS NULL
           LIMIT 1) AS root_name
  FROM products p
),
targets AS (
  SELECT md.root_name, array_agg(md.merchant_id ORDER BY md.merchant_id) AS ids
  FROM merchant_domain md
  GROUP BY md.root_name
),
moves AS (
  SELECT pr.product_id,
         t.ids[1 + (abs(('x' || substr(md5(pr.product_id), 1, 8))::bit(32)::int) % array_length(t.ids, 1))] AS new_merchant
  FROM prod_root pr
  JOIN merchant_domain md ON md.merchant_id = pr.merchant_id
  JOIN targets t ON t.root_name = pr.root_name
  WHERE pr.root_name IS NOT NULL
    AND md.root_name <> pr.root_name
)
UPDATE products p SET merchant_id = m.new_merchant
  FROM moves m WHERE p.product_id = m.product_id;

-- 2) Leaf-level refinement for health & beauty so food/supplements, perfume and hair
--    land at the right kind of store instead of any beauty shop.
WITH mapping(leaf_name, merchant_name) AS (VALUES
  ('Vitamin & Thực phẩm chức năng', 'VitaPlus'),
  ('Vitamin & Thực phẩm chức năng', 'BioVital Health'),
  ('Nước hoa', 'ScentHouse'),
  ('Chăm sóc tóc', 'HairCare Lab'),
  ('Trang điểm', 'PureCare Cosmetics'),
  ('Trang điểm', 'BeautyBar'),
  ('Trang điểm', 'Glow Beauty'),
  ('Trang điểm', 'PureGlow Store'),
  ('Chăm sóc da', 'PureCare Cosmetics'),
  ('Chăm sóc da', 'BeautyBar'),
  ('Chăm sóc da', 'Glow Beauty'),
  ('Chăm sóc da', 'PureGlow Store')
),
targets AS (
  SELECT mp.leaf_name, array_agg(m.merchant_id ORDER BY m.merchant_id) AS ids
  FROM mapping mp
  JOIN merchants m ON m.name = mp.merchant_name
  GROUP BY mp.leaf_name
),
prod_leaf AS (
  SELECT p.product_id, c.name AS leaf_name
  FROM products p
  JOIN categories c ON c.category_id = (p.category_ids->>0)
),
moves AS (
  SELECT pr.product_id,
         t.ids[1 + (abs(('x' || substr(md5(pr.product_id), 1, 8))::bit(32)::int) % array_length(t.ids, 1))] AS new_merchant
  FROM prod_leaf pr
  JOIN targets t ON t.leaf_name = pr.leaf_name
)
UPDATE products p SET merchant_id = m.new_merchant
  FROM moves m WHERE p.product_id = m.product_id;

-- 3) Reassign brands so the stated brand also fits the category.
WITH mapping(brand_name, root_name) AS (VALUES
  ('AirNest', 'Nhà thông minh'),
  ('Aroma', 'Sức khỏe & Làm đẹp'),
  ('AudioWave', 'Điện tử'),
  ('AutoNova', 'Ô tô & Xe máy'),
  ('CarryOn', 'Thời trang'),
  ('DriveMax', 'Ô tô & Xe máy'),
  ('Dược phẩm BioVital', 'Sức khỏe & Làm đẹp'),
  ('Dụng cụ thể thao FitLife', 'Thể thao & Dã ngoại'),
  ('FreshFarm', 'Nhà cửa & Bếp'),
  ('GemLuxe', 'Thời trang'),
  ('GreenHarvest', 'Nhà cửa & Bếp'),
  ('GuardHome', 'Nhà thông minh'),
  ('Lumina', 'Điện tử'),
  ('LuxTime', 'Thời trang'),
  ('Lõi công nghệ Nexus', 'Điện tử'),
  ('Mỹ phẩm GlowUp', 'Sức khỏe & Làm đẹp'),
  ('Nội thất KraftTech', 'Nhà cửa & Bếp'),
  ('PeakForm', 'Thể thao & Dã ngoại'),
  ('Phòng thí nghiệm Apex', 'Điện tử'),
  ('PixelForge', 'Điện tử'),
  ('PureGlow', 'Sức khỏe & Làm đẹp'),
  ('ScentAura', 'Sức khỏe & Làm đẹp'),
  ('ShadeLine', 'Thời trang'),
  ('StyleCraft', 'Thời trang'),
  ('Thiết bị gia dụng Zephyr', 'Nhà cửa & Bếp'),
  ('Thiết bị thông minh Vina', 'Điện tử'),
  ('Thời trang Elegance', 'Thời trang'),
  ('UrbanTrail', 'Thể thao & Dã ngoại'),
  ('Voltix', 'Điện tử')
),
brand_domain AS (
  SELECT b.brand_id, mp.root_name
  FROM brands b
  JOIN mapping mp ON mp.brand_name = b.name
),
prod_root AS (
  SELECT p.product_id, p.brand_id,
         (SELECT c.name
            FROM jsonb_array_elements_text(p.category_ids) AS cid
            JOIN categories c ON c.category_id = cid AND c.parent_id IS NULL
           LIMIT 1) AS root_name
  FROM products p
),
targets AS (
  SELECT bd.root_name, array_agg(bd.brand_id ORDER BY bd.brand_id) AS ids
  FROM brand_domain bd
  GROUP BY bd.root_name
),
moves AS (
  SELECT pr.product_id,
         t.ids[1 + (abs(('x' || substr(md5(pr.product_id), 1, 8))::bit(32)::int) % array_length(t.ids, 1))] AS new_brand
  FROM prod_root pr
  LEFT JOIN brand_domain bd ON bd.brand_id = pr.brand_id
  JOIN targets t ON t.root_name = pr.root_name
  WHERE pr.root_name IS NOT NULL
    AND (bd.root_name IS NULL OR bd.root_name <> pr.root_name)
)
UPDATE products p SET brand_id = m.new_brand
  FROM moves m WHERE p.product_id = m.product_id;

-- 4) Leaf-level brand refinement for health & beauty.
WITH mapping(leaf_name, brand_name) AS (VALUES
  ('Vitamin & Thực phẩm chức năng', 'Dược phẩm BioVital'),
  ('Nước hoa', 'Aroma'),
  ('Nước hoa', 'ScentAura'),
  ('Chăm sóc tóc', 'PureGlow'),
  ('Trang điểm', 'Mỹ phẩm GlowUp'),
  ('Trang điểm', 'PureGlow'),
  ('Chăm sóc da', 'Mỹ phẩm GlowUp'),
  ('Chăm sóc da', 'PureGlow')
),
targets AS (
  SELECT mp.leaf_name, array_agg(b.brand_id ORDER BY b.brand_id) AS ids
  FROM mapping mp
  JOIN brands b ON b.name = mp.brand_name
  GROUP BY mp.leaf_name
),
prod_leaf AS (
  SELECT p.product_id, c.name AS leaf_name
  FROM products p
  JOIN categories c ON c.category_id = (p.category_ids->>0)
),
moves AS (
  SELECT pr.product_id,
         t.ids[1 + (abs(('x' || substr(md5(pr.product_id), 1, 8))::bit(32)::int) % array_length(t.ids, 1))] AS new_brand
  FROM prod_leaf pr
  JOIN targets t ON t.leaf_name = pr.leaf_name
)
UPDATE products p SET brand_id = m.new_brand
  FROM moves m WHERE p.product_id = m.product_id;

-- Keep the JSON brand attribute in sync with the normalized brand.
UPDATE products p
   SET attributes = jsonb_set(p.attributes, '{brand}', to_jsonb(b.name), true)
  FROM brands b
 WHERE b.brand_id = p.brand_id
   AND p.attributes ? 'brand'
   AND p.attributes->>'brand' IS DISTINCT FROM b.name;
